pm.test("response", () => {
  pm.expect(pm.response.code).to.equal(404);
  pm.expect(pm.response.status).to.equal("Not Found");
  pm.expect(pm.response.reason()).to.equal("Not Found");
  pm.expect(pm.response.headers.get("content-type")).to.equal("application/json");
  pm.expect(pm.response.headers.has("X-Trace")).to.be.true;
  pm.expect(pm.response.headers.toObject()["X-Trace"]).to.equal("t");
  pm.expect(pm.response.json().error).to.equal("missing");
  pm.expect(pm.response.text()).to.include("missing");
  pm.expect(pm.response.responseTime).to.equal(12);
  pm.expect(pm.response.responseSize).to.equal(19);
});
pm.test("to.have", () => {
  pm.response.to.have.status("Not Found");
  pm.response.to.have.header("X-Trace", "t");
  pm.response.to.be.clientError;
  pm.response.to.be.notFound;
  pm.response.to.not.be.ok;
  pm.response.to.have.jsonBody("error", "missing");
  pm.response.to.be.json;
});
pm.test("ok fails", () => pm.response.to.be.ok);
